-- =========================================================
-- DỮ LIỆU DEMO CHO TRANG THỐNG KÊ (ĐẶC SẢN LÂM ĐỒNG)
--
-- CÁCH DÙNG:
--   1. Chạy sqldoan-moi.sql trước (tạo bảng + dữ liệu gốc).
--   2. Chạy file này MỘT lần trong HeidiSQL / MariaDB.
--
-- File này CÓ THỂ CHẠY LẠI NHIỀU LẦN: mỗi lần chạy sẽ xóa dữ liệu demo cũ
-- (đơn có ghi chú bắt đầu bằng "[Demo]" và khách demo.khachXX@example.com)
-- rồi tạo lại, nên dữ liệu thật của bạn không bị ảnh hưởng.
--
-- Ngày giờ được tính TƯƠNG ĐỐI so với hôm nay (NOW()), nên khi demo
-- biểu đồ luôn có số liệu của 12 tháng gần nhất.
--
-- Nội dung: 30 khách demo, 415 đơn hàng, 754 dòng sản phẩm, 1496 sự kiện xử lý đơn.
-- Mật khẩu của khách demo: 123456
-- =========================================================

SET NAMES utf8mb4;
USE dacsanlamdong;
SET @t = CURDATE();  -- mốc "hôm nay" để tính ngày tương đối

-- 1. Xóa dữ liệu demo cũ (nếu có), xóa từ bảng con lên bảng cha
--    Gồm: đơn có ghi chú "[Demo]" và mọi đơn của các khách demo.
DELETE FROM order_events WHERE order_id IN (
  SELECT id FROM orders WHERE note LIKE '[Demo]%'
     OR user_id IN (SELECT id FROM users WHERE email LIKE 'demo.khach%@example.com'));
DELETE FROM order_items WHERE order_id IN (
  SELECT id FROM orders WHERE note LIKE '[Demo]%'
     OR user_id IN (SELECT id FROM users WHERE email LIKE 'demo.khach%@example.com'));
DELETE FROM orders WHERE note LIKE '[Demo]%'
   OR user_id IN (SELECT id FROM users WHERE email LIKE 'demo.khach%@example.com');
DELETE FROM users WHERE email LIKE 'demo.khach%@example.com';

-- 2. Khách hàng demo (ngày đăng ký rải đều, khách mới tăng dần)

-- Hai khách có sẵn trong file gốc coi như đã đăng ký từ lâu
UPDATE users SET created_at = NOW() - INTERVAL 400 DAY
WHERE email IN ('khacha@gmail.com', 'khachb@gmail.com');

